from pysat.solvers import Glucose3
from pysat.card import *

# 16x16 Sudoku with 4x4 blocks
N = 16
BLOCK_SIZE = 4

# Fixed values from the problem
fixed = {
    5: 6, 13: 14, 14: 15, 18: 7, 22: 3, 26: 15, 27: 16,
    33: 10, 34: 11, 42: 3, 53: 10, 54: 11, 57: 6, 58: 7,
    69: 5, 71: 7, 80: 6, 81: 5, 83: 7, 84: 2, 85: 1, 94: 12,
    103: 15, 106: 4, 107: 3, 109: 5, 112: 14, 115: 15, 120: 6,
    135: 6, 136: 11, 140: 15, 141: 16, 148: 3, 150: 1,
    170: 1, 175: 6, 185: 8, 188: 3, 190: 1, 196: 8, 199: 5,
    201: 11, 203: 9, 208: 8, 218: 14, 240: 16, 241: 15,
    243: 13, 244: 12, 253: 3
}

# Create SAT solver
solver = Glucose3()

# Variable encoding: var(cell, value) = cell * N + value (1-indexed value, so value 1-16)
# cell ranges from 0 to 255, value from 1 to 16
# Variable index: cell * 16 + (value - 1), so 0 to 4095
def var(cell, value):
    return cell * 16 + (value - 1) + 1  # +1 for 1-indexed SAT vars

# Constraint 1: Each cell has exactly one value
for cell in range(N * N):
    # At least one value
    solver.add_clause([var(cell, v) for v in range(1, N + 1)])
    # At most one value (pairwise)
    for v1 in range(1, N + 1):
        for v2 in range(v1 + 1, N + 1):
            solver.add_clause([-var(cell, v1), -var(cell, v2)])

# Constraint 2: Each row has each value exactly once
for row in range(N):
    for value in range(1, N + 1):
        cells_in_row = [row * N + col for col in range(N)]
        # At least one cell in row has this value
        solver.add_clause([var(c, value) for c in cells_in_row])
        # At most one cell in row has this value
        for i in range(len(cells_in_row)):
            for j in range(i + 1, len(cells_in_row)):
                solver.add_clause([-var(cells_in_row[i], value), -var(cells_in_row[j], value)])

# Constraint 3: Each column has each value exactly once
for col in range(N):
    for value in range(1, N + 1):
        cells_in_col = [row * N + col for row in range(N)]
        # At least one cell in col has this value
        solver.add_clause([var(c, value) for c in cells_in_col])
        # At most one cell in col has this value
        for i in range(len(cells_in_col)):
            for j in range(i + 1, len(cells_in_col)):
                solver.add_clause([-var(cells_in_col[i], value), -var(cells_in_col[j], value)])

# Constraint 4: Each block has each value exactly once
for block_row in range(N // BLOCK_SIZE):
    for block_col in range(N // BLOCK_SIZE):
        for value in range(1, N + 1):
            cells_in_block = []
            for r in range(BLOCK_SIZE):
                for c in range(BLOCK_SIZE):
                    row = block_row * BLOCK_SIZE + r
                    col = block_col * BLOCK_SIZE + c
                    cells_in_block.append(row * N + col)
            # At least one cell in block has this value
            solver.add_clause([var(c, value) for c in cells_in_block])
            # At most one cell in block has this value
            for i in range(len(cells_in_block)):
                for j in range(i + 1, len(cells_in_block)):
                    solver.add_clause([-var(cells_in_block[i], value), -var(cells_in_block[j], value)])

# Fixed values
for cell, value in fixed.items():
    solver.add_clause([var(cell, value)])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    # Extract solution
    grid = [0] * (N * N)
    for cell in range(N * N):
        for value in range(1, N + 1):
            if var(cell, value) in model:
                grid[cell] = value
                break

    # Verify solution
    print("Solution found!")

    # Print grid
    for row in range(N):
        row_vals = grid[row*N:(row+1)*N]
        print(" ".join(f"{v:2d}" for v in row_vals))

    # Verify constraints
    # Check rows
    for row in range(N):
        vals = set(grid[row*N:(row+1)*N])
        assert vals == set(range(1, 17)), f"Row {row} invalid: {vals}"

    # Check columns
    for col in range(N):
        vals = set(grid[row*N + col] for row in range(N))
        assert vals == set(range(1, 17)), f"Col {col} invalid"

    # Check blocks
    for block_row in range(N // BLOCK_SIZE):
        for block_col in range(N // BLOCK_SIZE):
            vals = set()
            for r in range(BLOCK_SIZE):
                for c in range(BLOCK_SIZE):
                    row = block_row * BLOCK_SIZE + r
                    col = block_col * BLOCK_SIZE + c
                    vals.add(grid[row * N + col])
            assert vals == set(range(1, 17)), f"Block ({block_row},{block_col}) invalid"

    # Check fixed values
    for cell, value in fixed.items():
        assert grid[cell] == value, f"Fixed value at {cell} violated: {grid[cell]} != {value}"

    print("All constraints verified!")
    print(f"Solution: {grid}")
else:
    print("UNSATISFIABLE")

solver.delete()
